        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Da Pd e M5S solo delegazioni. I due leader evitano la piazza",
        "testo_it": "I leader di PD e M5S, Schlein e Conte, hanno evitato la piazza delle proteste \"No Kings\" a Roma, inviando solo delegazioni.",
        "priorita": "Bassa",
        "id_gruppo": 19,
        "link": "https://ilmanifesto.it/da-pd-e-m5s-solo-delegazioni-i-due-leader-evitano-la-piazza",
        "orario": "00:07",
